class Solution {
public:
    string longestDupSubstring(string s) {
        int n = s.size();
        vector<int> nums(n);
        for (int i = 0; i < n; ++i) nums[i] = s[i] - 'a';
        unsigned long long mod = 1000000007ULL;

        auto search = [&](int L) -> int {
            unsigned long long h = 0, base_L = 1;
            for (int i = 0; i < L; ++i) {
                h = (h * 26 + nums[i]) % mod;
                if (i > 0) base_L = (base_L * 26) % mod;
            }
            unordered_map<unsigned long long, vector<int>> seen;
            seen[h].push_back(0);
            for (int start = 1; start <= n - L; ++start) {
                h = (h + mod - (nums[start - 1] * base_L) % mod) % mod;
                h = (h * 26 + nums[start + L - 1]) % mod;
                if (seen.find(h) != seen.end()) {
                    for (int prev : seen[h]) {
                        if (s.compare(prev, L, s, start, L) == 0) return start;
                    }
                }
                seen[h].push_back(start);
            }
            return -1;
        };

        int low = 1, high = n - 1;
        int best_start = -1, best_len = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int start = search(mid);
            if (start != -1) {
                best_start = start;
                best_len = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return best_len > 0 ? s.substr(best_start, best_len) : "";
    }
};

class Solution {
    public String longestDupSubstring(String s) {
        int n = s.length();
        int[] nums = new int[n];
        for (int i = 0; i < n; ++i) nums[i] = s.charAt(i) - 'a';
        long mod = 1000000007L;

        int low = 1, high = n - 1;
        int bestStart = -1, bestLen = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int start = search(nums, s, mid, mod);
            if (start != -1) {
                bestStart = start;
                bestLen = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return bestLen > 0 ? s.substring(bestStart, bestStart + bestLen) : "";
    }

    private int search(int[] nums, String s, int L, long mod) {
        int n = nums.length;
        long h = 0, baseL = 1;
        for (int i = 0; i < L; ++i) {
            h = (h * 26 + nums[i]) % mod;
            if (i > 0) baseL = (baseL * 26) % mod;
        }
        Map<Long, List<Integer>> seen = new HashMap<>();
        seen.computeIfAbsent(h, k -> new ArrayList<>()).add(0);
        for (int start = 1; start <= n - L; ++start) {
            h = (h + mod - (nums[start - 1] * baseL) % mod) % mod;
            h = (h * 26 + nums[start + L - 1]) % mod;
            if (seen.containsKey(h)) {
                String sub = s.substring(start, start + L);
                for (int prev : seen.get(h)) {
                    if (s.startsWith(sub, prev)) return start;
                }
            }
            seen.computeIfAbsent(h, k -> new ArrayList<>()).add(start);
        }
        return -1;
    }
}

var longestDupSubstring = function(s) {
    const n = s.length;
    let low = 1, high = n - 1;
    let bestStart = -1, bestLen = 0;

    const check = (L) => {
        const seen = new Set();
        for (let i = 0; i <= n - L; i++) {
            const sub = s.slice(i, i + L);
            if (seen.has(sub)) return i;
            seen.add(sub);
        }
        return -1;
    };

    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        const start = check(mid);
        if (start !== -1) {
            bestStart = start;
            bestLen = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return bestLen > 0 ? s.slice(bestStart, bestStart + bestLen) : "";
};
